from taf.transport.ssh.exceptions import ConnectionError
from ute_core.exception import CoreException

SSHClientException = ConnectionError


class SSHExecutionError(SSHClientException):
    """Exception is raised if ssh error is occurred."""


class SSHIsAlreadyEstablished(SSHClientException):
    """Exception is raised if ssh is already established"""


class SSHServiceUnavailable(SSHClientException):
    """Exception is raised if ssh service is unavailable."""


class RemoteHostUnreachable(SSHClientException):
    """Exception is raised if remote host ssh cannot be reached."""


class FsmAccessException(CoreException):
    """Main FsmAccess library exception."""


class WrongPartition(FsmAccessException):
    """Exception is raised if wrong partition is defined."""


class UnknownFsmHwVersion(FsmAccessException):
    """Exception is raised if Fsm has unknown HW version."""


class TargetBDIsNotValid(FsmAccessException):
    """Exception is raised if TargetBD file has not valid form."""


class MultipleFilesError(FsmAccessException):
    """Exception is raised if more than one target file exists."""


class SymbolicLinkError(FsmAccessException):
    """Exception is raised if symbolic link does not exist."""


class FileDoNotExist(FsmAccessException):
    """Exception is raised if given file does not exist."""


class DictionaryDoNotExist(FsmAccessException):
    """Exception is raised if dictionary does not exist."""


class NotAllHostsFound(FsmAccessException):
    """Exception is raised when at least one host is not found."""
